import * as path from "node:path";
import * as sandcastle from "@ai-hero/sandcastle";
import { noSandbox } from "@ai-hero/sandcastle/sandboxes/no-sandbox";
import { claudeAgent, writeJson } from "../shared/common";
import { extractionPrompt } from "../shared/extraction-prompt";
import { runWithExtraction } from "../shared/run-with-extraction";
import { specDecompositionSchema } from "./decomposition-schema";

// This loop writes tickets, not code, and the workflow step after this one is
// what actually creates them.
const result = await runWithExtraction({
  name: "decompose",
  agent: claudeAgent(),
  sandbox: noSandbox(),
  logging: { type: "stdout" },
  promptFile: path.join(import.meta.dirname, "decompose-prompt.md"),
  output: sandcastle.Output.object({
    tag: "queue",
    schema: specDecompositionSchema,
  }),
  extractionPrompt: extractionPrompt("queue", specDecompositionSchema),
});

writeJson("queue.json", result.output);

import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import {
  run,
  type OutputObjectDefinition,
  type RunOptions,
  type RunResult,
} from "@ai-hero/sandcastle";

export type RunWithExtractionOptions<T> = Omit<RunOptions, "output"> & {
  readonly output: OutputObjectDefinition<T>;
  readonly extractionPrompt: string;
  /**
   * Extra attempts after the first if extraction or validation fails. Forwarded
   * to `Output`'s built-in `maxRetries`, which resumes the extraction session
   * and feeds back the error so the agent can re-emit a corrected tag.
   * Default: `2` (three attempts total). Ignored when the agent can't resume.
   */
  readonly maxRetries?: number;
};

// Two passes over one session. The first run does the work with the whole
// toolset. The second resumes that session and asks only for the structured
// output, so the answer is extracted from everything the first run read.
export async function runWithExtraction<T>(
  options: RunWithExtractionOptions<T>
): Promise<RunResult & { output: T }> {
  const {
    output,
    extractionPrompt,
    maxRetries = 2,
    ...produceOptions
  } = options;

  // Agents that can't resume a session (OpenCode) get no second pass and no
  // retries, so they emit the structured output at the end of the work itself.
  if (!produceOptions.agent.sessionStorage) {
    return run({
      ...produceOptions,
      ...appendToPrompt(produceOptions, extractionPrompt),
      output: { ...output, maxRetries: 0 },
    });
  }

  const produce = await run(produceOptions);
  const sessionId = produce.iterations.at(-1)?.sessionId;

  if (!sessionId) {
    throw new Error(
      "Cannot extract structured output because the produce run had no session id."
    );
  }

  const { promptArgs: _promptArgs, ...extractionOptions } = produceOptions;
  const extractionOutput: OutputObjectDefinition<T> = {
    ...output,
    maxRetries,
  };
  const extraction = await run({
    ...extractionOptions,
    name: produceOptions.name ? `${produceOptions.name} (extract)` : undefined,
    promptFile: undefined,
    prompt: extractionPrompt,
    resumeSession: sessionId,
    output: extractionOutput,
  });

  return { ...produce, output: extraction.output };
}

// A prompt file is copied with the instructions appended, so `promptArgs`
// substitution still applies to it.
const appendToPrompt = (
  options: Pick<RunOptions, "prompt" | "promptFile">,
  extractionPrompt: string
): Pick<RunOptions, "prompt" | "promptFile"> => {
  const suffix = [
    "",
    "",
    "When the task above is done, end with this final message. These rules bind that message only.",
    "",
    extractionPrompt,
  ].join("\n");

  if (options.promptFile === undefined) {
    return { prompt: `${options.prompt ?? ""}${suffix}` };
  }

  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "run-with-extraction-"));
  const promptFile = path.join(dir, path.basename(options.promptFile));
  fs.writeFileSync(
    promptFile,
    `${fs.readFileSync(options.promptFile, "utf8")}${suffix}`
  );
  return { promptFile };
};

import { z } from "zod/v4";

// The second pass of `runWithExtraction`. The schema is printed into the
// prompt as JSON Schema, descriptions and all, so the zod schema is the one
// place the shape of the answer is written down.
export const extractionPrompt = (tag: string, schema: z.ZodType): string =>
  [
    `Reply with one \`<${tag}>\` block and nothing else. Inside it, put one JSON value that matches this JSON Schema:`,
    "",
    "```json",
    JSON.stringify(z.toJSONSchema(schema), null, 2),
    "```",
    "",
    "Answer from what you have already read, with no tool calls.",
    "",
    `<${tag}>`,
    "{ ...the JSON value... }",
    `</${tag}>`,
  ].join("\n");

import Database from "better-sqlite3";
import { drizzle } from "drizzle-orm/better-sqlite3";
import { migrate } from "drizzle-orm/better-sqlite3/migrator";
import path from "path";
import { fileURLToPath } from "url";
import * as schema from "~/db/schema";
import { markdown } from "~/lib/text";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const migrationsFolder = path.resolve(__dirname, "../../drizzle");

/**
 * Creates a fresh in-memory SQLite database with all tables for testing.
 * Each call returns a new isolated database instance.
 *
 * Uses the same Drizzle migrations as the live database, ensuring
 * test and production schemas are always in sync.
 */
export function createTestDb() {
  const sqlite = new Database(":memory:");
  sqlite.pragma("journal_mode = WAL");
  sqlite.pragma("foreign_keys = ON");

  const testDb = drizzle(sqlite, { schema });

  migrate(testDb, { migrationsFolder });

  return testDb;
}

export type TestDb = ReturnType<typeof createTestDb>;

/**
 * Seeds a minimal set of base data (user, category, course) that most tests need.
 * Returns the created IDs for use in test assertions.
 */
export function seedBaseData(testDb: TestDb) {
  const user = testDb
    .insert(schema.users)
    .values({
      name: "Test User",
      email: "test@example.com",
      role: schema.UserRole.Student,
    })
    .returning()
    .get();

  const instructor = testDb
    .insert(schema.users)
    .values({
      name: "Test Instructor",
      email: "instructor@example.com",
      role: schema.UserRole.Instructor,
    })
    .returning()
    .get();

  const category = testDb
    .insert(schema.categories)
    .values({ name: "Programming", slug: "programming" })
    .returning()
    .get();

  const course = testDb
    .insert(schema.courses)
    .values({
      title: "Test Course",
      slug: "test-course",
      description: "A test course",
      salesCopy: markdown("## Test Course\n\nSales copy for the test course."),
      instructorId: instructor.id,
      categoryId: category.id,
      status: schema.CourseStatus.Published,
    })
    .returning()
    .get();

  return { user, instructor, category, course };
}

import { describe, expect, it, vi } from "vitest";
import { discoverModelIds, parseModelIds } from "./model-discovery";

describe("parseModelIds", () => {
  it("parses model IDs from a standard OpenAI-compatible response", () => {
    expect(
      parseModelIds({ data: [{ id: "qwen3:8b" }, { id: "deepseek-r1" }] })
    ).toEqual(["qwen3:8b", "deepseek-r1"]);
  });

  it("ignores entries without usable string IDs", () => {
    expect(
      parseModelIds({
        data: [{ id: "qwen3:8b" }, {}, { id: 42 }, { id: "" }, { id: "   " }],
      })
    ).toEqual(["qwen3:8b"]);
  });

  it.each([null, {}, { data: {} }])(
    "returns no IDs for malformed data: %j",
    (body) => {
      expect(parseModelIds(body)).toEqual([]);
    }
  );
});

describe("discoverModelIds", () => {
  it("queries the custom origin's /v1/models endpoint once without credentials", async () => {
    const fetchImpl = vi.fn().mockResolvedValue(
      new Response(JSON.stringify({ data: [{ id: "local-model" }] }), {
        status: 200,
        headers: { "content-type": "application/json" },
      })
    );

    await expect(
      discoverModelIds("http://localhost:11434/a/path", { fetchImpl })
    ).resolves.toEqual(["local-model"]);

    expect(fetchImpl).toHaveBeenCalledOnce();
    const [url, init] = fetchImpl.mock.calls[0];
    expect(url).toBe("http://localhost:11434/v1/models");
    expect(init).not.toHaveProperty("headers");
    expect(init.signal).toBeInstanceOf(AbortSignal);
  });

  it.each([
    ["network failure", () => Promise.reject(new Error("offline"))],
    [
      "unsuccessful status",
      () => Promise.resolve(new Response("no", { status: 500 })),
    ],
    ["malformed JSON", () => Promise.resolve(new Response("not json"))],
  ])("falls back to no IDs after %s", async (_name, implementation) => {
    await expect(
      discoverModelIds("http://localhost:11434", {
        fetchImpl: vi.fn(implementation),
      })
    ).resolves.toEqual([]);
  });

  it("aborts discovery after the configured timeout and falls back to no IDs", async () => {
    vi.useFakeTimers();
    const fetchImpl = vi.fn((_url: RequestInfo | URL, init?: RequestInit) => {
      return new Promise<Response>((_resolve, reject) => {
        init?.signal?.addEventListener("abort", () =>
          reject(init.signal?.reason)
        );
      });
    });

    const result = discoverModelIds("http://localhost:11434", {
      fetchImpl,
      timeoutMs: 25,
    });
    await vi.advanceTimersByTimeAsync(25);

    await expect(result).resolves.toEqual([]);
    vi.useRealTimers();
  });
});

import { describe, it, expect, beforeEach } from "vitest";
import { createTestDb, seedBaseData, type TestDb } from "~/test/setup";
import { eq } from "drizzle-orm";
import * as schema from "~/db/schema";
import { UserRole } from "~/db/schema";
import { setCurrentUserId, setDevCountry } from "~/lib/session";
import { createPeople } from "../person.server";

let db: TestDb;
let people: ReturnType<typeof createPeople>;
let base: ReturnType<typeof seedBaseData>;

beforeEach(() => {
  db = createTestDb();
  base = seedBaseData(db);
  people = createPeople(db);
});

function makeRequest(headers: Record<string, string> = {}) {
  return new Request("http://localhost:3000/", { headers });
}

/** Signs in through the real session cookie, as the DevUI panel does. */
async function signedInRequest(
  userId: number,
  {
    devCountry,
    headerCountry,
  }: { devCountry?: string; headerCountry?: string } = {}
) {
  let setCookie = await setCurrentUserId(makeRequest(), userId);
  if (devCountry) {
    setCookie = await setDevCountry(
      makeRequest({ Cookie: cookieFrom(setCookie) }),
      devCountry
    );
  }
  const headers: Record<string, string> = { Cookie: cookieFrom(setCookie) };
  if (headerCountry) headers["CF-IPCountry"] = headerCountry;
  return makeRequest(headers);
}

function cookieFrom(setCookie: string) {
  return setCookie.split(";")[0];
}

describe("getPerson", () => {
  it("gives null when signed out", async () => {
    expect(await people.getPerson(makeRequest())).toBeNull();
  });

  it("uses the country header when there's no dev country", async () => {
    const request = await signedInRequest(base.user.id, {
      headerCountry: "BR",
    });

    expect(await people.getPerson(request)).toEqual({
      id: base.user.id,
      role: "student",
      country: "BR",
    });
  });

  it("prefers the dev country over the country header", async () => {
    const request = await signedInRequest(base.user.id, {
      devCountry: "IN",
      headerCountry: "US",
    });

    expect((await people.getPerson(request))?.country).toBe("IN");
  });

  it("gives a null country when the country is unknown", async () => {
    const request = await signedInRequest(base.user.id, {
      headerCountry: "XX",
    });

    expect((await people.getPerson(request))?.country).toBeNull();
  });

  it("calls a Platform Admin platform-admin", async () => {
    const platformAdmin = db
      .insert(schema.users)
      .values({
        name: "Pat Admin",
        email: "pat@example.com",
        role: UserRole.Admin,
      })
      .returning()
      .get();

    const person = await people.getPerson(
      await signedInRequest(platformAdmin.id)
    );

    expect(person?.role).toBe("platform-admin");
  });

  it("gives null when the session points at a deleted user", async () => {
    const request = await signedInRequest(base.user.id);
    db.delete(schema.users).where(eq(schema.users.id, base.user.id)).run();

    expect(await people.getPerson(request)).toBeNull();
  });
});

describe("requirePerson", () => {
  it("returns the Person when signed in", async () => {
    const request = await signedInRequest(base.instructor.id);

    expect(await people.requirePerson(request)).toEqual({
      id: base.instructor.id,
      role: "instructor",
      country: null,
    });
  });

  it("throws 401 asking to select a user when signed out", async () => {
    const thrown = await people
      .requirePerson(makeRequest())
      .catch((error) => error);

    expect(thrown).toMatchObject({
      init: { status: 401 },
      data: "Select a user from the DevUI panel.",
    });
  });
});

describe("requirePlatformAdmin", () => {
  function addPlatformAdmin() {
    return db
      .insert(schema.users)
      .values({
        name: "Pat Admin",
        email: "pat@example.com",
        role: UserRole.Admin,
      })
      .returning()
      .get();
  }

  it("throws 401 asking to select a user when signed out", async () => {
    const thrown = await people
      .requirePlatformAdmin(makeRequest())
      .catch((error) => error);

    expect(thrown).toMatchObject({
      init: { status: 401 },
      data: "Select a user from the DevUI panel.",
    });
  });

  it("throws 403 for a Student", async () => {
    const request = await signedInRequest(base.user.id);

    const thrown = await people
      .requirePlatformAdmin(request)
      .catch((error) => error);

    expect(thrown).toMatchObject({
      init: { status: 403 },
      data: "Only Platform Admins can do that.",
    });
  });

  it("throws 403 for an Instructor", async () => {
    const request = await signedInRequest(base.instructor.id);

    const thrown = await people
      .requirePlatformAdmin(request)
      .catch((error) => error);

    expect(thrown).toMatchObject({
      init: { status: 403 },
      data: "Only Platform Admins can do that.",
    });
  });

  it("returns the Person for a Platform Admin", async () => {
    const platformAdmin = addPlatformAdmin();
    const request = await signedInRequest(platformAdmin.id, {
      headerCountry: "DE",
    });

    expect(await people.requirePlatformAdmin(request)).toEqual({
      id: platformAdmin.id,
      role: "platform-admin",
      country: "DE",
    });
  });
});

describe("requireInstructorOrPlatformAdmin", () => {
  it("returns the Person for an Instructor", async () => {
    const request = await signedInRequest(base.instructor.id);

    expect(await people.requireInstructorOrPlatformAdmin(request)).toEqual({
      id: base.instructor.id,
      role: "instructor",
      country: null,
    });
  });

  it("throws 403 for a Student", async () => {
    const request = await signedInRequest(base.user.id);

    const thrown = await people
      .requireInstructorOrPlatformAdmin(request)
      .catch((error) => error);

    expect(thrown).toMatchObject({
      init: { status: 403 },
      data: "Only Instructors and Platform Admins can do that.",
    });
  });

  it("returns the Person for a Platform Admin", async () => {
    const platformAdmin = db
      .insert(schema.users)
      .values({
        name: "Pat Admin",
        email: "pat@example.com",
        role: UserRole.Admin,
      })
      .returning()
      .get();

    const person = await people.requireInstructorOrPlatformAdmin(
      await signedInRequest(platformAdmin.id)
    );

    expect(person).toEqual({
      id: platformAdmin.id,
      role: "platform-admin",
      country: null,
    });
  });

  it("throws 401 when signed out", async () => {
    const thrown = await people
      .requireInstructorOrPlatformAdmin(makeRequest())
      .catch((error) => error);

    expect(thrown).toMatchObject({
      init: { status: 401 },
      data: "Select a user from the DevUI panel.",
    });
  });
});

import { describe, it, expect, beforeEach } from "vitest";
import { createTestDb, seedBaseData, type TestDb } from "~/test/setup";
import { eq } from "drizzle-orm";
import * as schema from "~/db/schema";
import { setCurrentUserId } from "~/lib/session";
import { createCoursePermissions } from "../course-permissions.server";
import type { Person } from "../person.server";

let db: TestDb;
let permissions: ReturnType<typeof createCoursePermissions>;
let base: ReturnType<typeof seedBaseData>;

beforeEach(() => {
  db = createTestDb();
  base = seedBaseData(db);
  permissions = createCoursePermissions(db);
});

// ─── Fixtures ───

function owningInstructor(country: string | null = null): Person {
  return { id: base.instructor.id, role: "instructor", country };
}

function addUser(
  name: string,
  role: schema.UserRole = schema.UserRole.Student
) {
  return db
    .insert(schema.users)
    .values({ name, email: `${name.replace(/ /g, ".")}@example.com`, role })
    .returning()
    .get();
}

function asPerson(
  user: { id: number },
  role: Person["role"],
  country: string | null = null
): Person {
  return { id: user.id, role, country };
}

function platformAdmin(country: string | null = null): Person {
  return asPerson(
    addUser("Pat Admin", schema.UserRole.Admin),
    "platform-admin",
    country
  );
}

function student(country: string | null = null): Person {
  return asPerson(base.user, "student", country);
}

function enroll(userId: number, courseId = base.course.id) {
  db.insert(schema.enrollments).values({ userId, courseId }).run();
}

let slugCounter = 0;
function addCourse(instructorId = base.instructor.id) {
  slugCounter += 1;
  return db
    .insert(schema.courses)
    .values({
      title: `Other Course ${slugCounter}`,
      slug: `other-course-${slugCounter}`,
      description: "Another course",
      salesCopy: base.course.salesCopy,
      instructorId,
      categoryId: base.category.id,
      status: schema.CourseStatus.Published,
    })
    .returning()
    .get();
}

function addModule(courseId = base.course.id) {
  return db
    .insert(schema.modules)
    .values({ courseId, title: "A module", position: 1 })
    .returning()
    .get();
}

function addLesson(moduleId: number) {
  return db
    .insert(schema.lessons)
    .values({ moduleId, title: "A lesson", position: 1 })
    .returning()
    .get();
}

function setPrice(price: number, pppEnabled = true, courseId = base.course.id) {
  db.update(schema.courses)
    .set({ price, pppEnabled })
    .where(eq(schema.courses.id, courseId))
    .run();
}

function buy(
  userId: number,
  country: string | null,
  createdAt = "2026-01-01T00:00:00.000Z",
  courseId = base.course.id
) {
  return db
    .insert(schema.purchases)
    .values({ userId, courseId, amountPaid: 5000, country, createdAt })
    .returning()
    .get();
}

/** A Team Licence: a Purchase with Seats. */
function buySeats(
  userId: number,
  country: string | null,
  createdAt = "2026-01-01T00:00:00.000Z"
) {
  const purchase = buy(userId, country, createdAt);
  const team = db.insert(schema.teams).values({}).returning().get();
  return db
    .insert(schema.coupons)
    .values({
      teamId: team.id,
      courseId: base.course.id,
      code: `SEAT-${purchase.id}`,
      purchaseId: purchase.id,
    })
    .returning()
    .get();
}

function decideOnCourse(person: Person | null) {
  return permissions.decide(person, { courseId: base.course.id });
}

function makeRequest(headers: Record<string, string> = {}) {
  return new Request("http://localhost:3000/", { headers });
}

/** Signs in through the real session cookie, as the DevUI panel does. */
async function signedInRequest(userId: number, headerCountry?: string) {
  const setCookie = await setCurrentUserId(makeRequest(), userId);
  const headers: Record<string, string> = { Cookie: setCookie.split(";")[0] };
  if (headerCountry) headers["CF-IPCountry"] = headerCountry;
  return makeRequest(headers);
}

const NOT_OWNER = {
  allowed: false,
  reason: { kind: "not-owning-instructor-or-platform-admin" },
};

describe("decide", () => {
  it("lets the owning Instructor view and manage, but not take, the course", () => {
    const decisions = permissions.decide(owningInstructor(), {
      courseId: base.course.id,
    });

    expect(decisions).toMatchObject({
      found: true,
      course: { id: base.course.id },
      person: owningInstructor(),
      view: { allowed: true },
      take: { allowed: false, reason: { kind: "not-enrolled" } },
      manage: { allowed: true },
    });
  });

  it("lets a Platform Admin view and manage, but not take, any course", () => {
    expect(decideOnCourse(platformAdmin())).toMatchObject({
      view: { allowed: true },
      take: { allowed: false, reason: { kind: "not-enrolled" } },
      manage: { allowed: true },
    });
  });

  it("lets an enrolled Student view and take, but not manage, the course", () => {
    enroll(base.user.id);

    expect(decideOnCourse(student())).toMatchObject({
      view: { allowed: true },
      take: { allowed: true },
      manage: NOT_OWNER,
    });
  });

  it("refuses an unenrolled Student everything", () => {
    expect(decideOnCourse(student())).toMatchObject({
      view: { allowed: false, reason: { kind: "not-enrolled" } },
      take: { allowed: false, reason: { kind: "not-enrolled" } },
      manage: NOT_OWNER,
    });
  });

  it("refuses nobody everything, because they're signed out", () => {
    const signedOut = { allowed: false, reason: { kind: "signed-out" } };

    expect(decideOnCourse(null)).toEqual({
      found: true,
      course: expect.objectContaining({ id: base.course.id }),
      person: null,
      enrolled: false,
      view: signedOut,
      take: signedOut,
      manage: signedOut,
    });
  });

  it("refuses another Instructor the right to manage a course they don't own", () => {
    const other = asPerson(
      addUser("Other Instructor", schema.UserRole.Instructor),
      "instructor"
    );

    expect(decideOnCourse(other)).toMatchObject({ manage: NOT_OWNER });
  });

  it("lets an owning Instructor whose role is no longer Instructor manage the course", () => {
    const demoted = asPerson(base.instructor, "student");

    expect(decideOnCourse(demoted)).toMatchObject({
      view: { allowed: true },
      manage: { allowed: true },
    });
  });

  it("lets an Instructor or Platform Admin with an Enrollment take the course", () => {
    enroll(base.instructor.id);

    expect(decideOnCourse(owningInstructor())).toMatchObject({
      take: { allowed: true },
    });
  });
});

describe("decide: Enrollment", () => {
  it("says an enrolled Student is enrolled", () => {
    enroll(base.user.id);

    expect(decideOnCourse(student())).toMatchObject({ enrolled: true });
  });

  it("says an unenrolled Student, owning Instructor or Platform Admin is not enrolled", () => {
    expect(decideOnCourse(student())).toMatchObject({ enrolled: false });
    expect(decideOnCourse(owningInstructor())).toMatchObject({
      enrolled: false,
    });
    expect(decideOnCourse(platformAdmin())).toMatchObject({ enrolled: false });
  });

  it("says a Student under Country Lock is still enrolled", () => {
    setPrice(10000);
    enroll(base.user.id);
    buy(base.user.id, "IN");

    expect(decideOnCourse(student("GB"))).toMatchObject({
      enrolled: true,
      take: { allowed: false, reason: { kind: "country-lock" } },
    });
  });
});

describe("decide: Country Lock", () => {
  const locked = (purchaseCountry: string, currentCountry: string) => ({
    allowed: false,
    reason: { kind: "country-lock", purchaseCountry, currentCountry },
  });

  beforeEach(() => {
    setPrice(10000);
    enroll(base.user.id);
  });

  it("locks a Student who bought at a Purchasing-Power Price out of view and take in another country", () => {
    buy(base.user.id, "IN");

    expect(decideOnCourse(student("GB"))).toMatchObject({
      view: locked("IN", "GB"),
      take: locked("IN", "GB"),
    });
  });

  it("doesn't lock a Student in the country they bought in", () => {
    buy(base.user.id, "IN");

    expect(decideOnCourse(student("IN"))).toMatchObject({
      view: { allowed: true },
      take: { allowed: true },
    });
  });

  it("doesn't lock a full-price Purchase", () => {
